window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2022-national_paper_a_liberal"]=[{"id":"2022-national_paper_a_liberal-q01","paperId":"2022-national_paper_a_liberal","number":1,"type":"single","score":5,"lessonIds":["1.3"],"difficulty":"基础","hint":"先从 A 的五个数里挑出满足 0≤x<2.5 的数。","legacy":false,"legacyReason":"","searchText":"已知集合 A=\\{-2,-1,0,1,2\\} ， B=\\{x\\mid 0\\le x<\\dfrac{5}{2}\\} ，则 A\\cap B= （ ） \\{0,1,2\\} \\{-2,-1,0\\} \\{0,1\\} \\{1,2\\}","questionHtml":"已知集合 <span class=\"gk-math\" data-tex=\"A=\\{-2,-1,0,1,2\\}\">A=\\{-2,-1,0,1,2\\}</span>，<span class=\"gk-math\" data-tex=\"B=\\{x\\mid 0\\le x&lt;\\dfrac{5}{2}\\}\">B=\\{x\\mid 0\\le x&lt;\\dfrac{5}{2}\\}</span>，则 <span class=\"gk-math\" data-tex=\"A\\cap B=\">A\\cap B=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{0,1,2\\}\">\\{0,1,2\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-2,-1,0\\}\">\\{-2,-1,0\\}</span>","<span class=\"gk-math\" data-tex=\"\\{0,1\\}\">\\{0,1\\}</span>","<span class=\"gk-math\" data-tex=\"\\{1,2\\}\">\\{1,2\\}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"B=\\{x\\mid 0\\le x&lt;2.5\\}\">B=\\{x\\mid 0\\le x&lt;2.5\\}</span> 可知 <span class=\"gk-math\" data-tex=\"B\">B</span> 中元素为 <span class=\"gk-math\" data-tex=\"0\\le x&lt;2.5\">0\\le x&lt;2.5</span> 的实数. 在 <span class=\"gk-math\" data-tex=\"A=\\{-2,-1,0,1,2\\}\">A=\\{-2,-1,0,1,2\\}</span> 中满足该条件的有 <span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，所以 <span class=\"gk-math\" data-tex=\"A\\cap B=\\{0,1,2\\}\">A\\cap B=\\{0,1,2\\}</span>，答案为 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q02","paperId":"2022-national_paper_a_liberal","number":2,"type":"single","score":5,"lessonIds":["9.2"],"difficulty":"基础","hint":"把讲座前后各十个正确率分别排序，再比较中位数、平均数和分散程度。","legacy":false,"legacyReason":"","searchText":"某社区通过公益讲座以普及社区居民的垃圾分类知识. 为了解讲座效果，随机抽取 10 位社区居民，让他们在讲座前和讲座后各回答一份垃圾分类知识问卷，这 10 位社区居民在讲座前和讲座后问卷答题的正确率如下图： 则（ ） 讲座前问卷答题的正确率的中位数小于 70\\% 讲座后问卷答题的正确率的平均数大于 85\\% 讲座前问卷答题的正确率的标准差小于讲座后正确率的标准差 讲座后问卷答题的正确率的极差大于讲座前正确率的极差","questionHtml":"某社区通过公益讲座以普及社区居民的垃圾分类知识. 为了解讲座效果，随机抽取 <span class=\"gk-math\" data-tex=\"10\">10</span> 位社区居民，让他们在讲座前和讲座后各回答一份垃圾分类知识问卷，这 <span class=\"gk-math\" data-tex=\"10\">10</span> 位社区居民在讲座前和讲座后问卷答题的正确率如下图：<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,955px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q2_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q2_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"939\" height=\"522\" style=\"aspect-ratio:939/522;width:100%\" loading=\"lazy\"></button></figure><br><br>则（ ）","optionsHtml":["讲座前问卷答题的正确率的中位数小于 <span class=\"gk-math\" data-tex=\"70\\%\">70\\%</span>","讲座后问卷答题的正确率的平均数大于 <span class=\"gk-math\" data-tex=\"85\\%\">85\\%</span>","讲座前问卷答题的正确率的标准差小于讲座后正确率的标准差","讲座后问卷答题的正确率的极差大于讲座前正确率的极差"],"answerHtml":"B","answerKey":"B","solutionHtml":"由图读取数据：讲座前（<span class=\"gk-math\" data-tex=\"*\">*</span>）的正确率依次为 <span class=\"gk-math\" data-tex=\"65\">65</span>，<span class=\"gk-math\" data-tex=\"60\">60</span>，<span class=\"gk-math\" data-tex=\"70\">70</span>，<span class=\"gk-math\" data-tex=\"60\">60</span>，<span class=\"gk-math\" data-tex=\"65\">65</span>，<span class=\"gk-math\" data-tex=\"75\">75</span>，<span class=\"gk-math\" data-tex=\"90\">90</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"80\">80</span>，<span class=\"gk-math\" data-tex=\"95\">95</span>；讲座后（<span class=\"gk-math\" data-tex=\"\\bullet\">\\bullet</span>）的正确率依次为 <span class=\"gk-math\" data-tex=\"90\">90</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"80\">80</span>，<span class=\"gk-math\" data-tex=\"90\">90</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"95\">95</span>，<span class=\"gk-math\" data-tex=\"100\">100</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"100\">100</span>.<br><br>讲座后正确率的平均数为 <span class=\"gk-math\" data-tex=\"\\dfrac{90+85+80+90+85+85+95+100+85+100}{10}=89.5&gt;85\">\\dfrac{90+85+80+90+85+85+95+100+85+100}{10}=89.5&gt;85</span>，B 正确. 讲座前正确率从小到大排列为 <span class=\"gk-math\" data-tex=\"60\">60</span>，<span class=\"gk-math\" data-tex=\"60\">60</span>，<span class=\"gk-math\" data-tex=\"65\">65</span>，<span class=\"gk-math\" data-tex=\"65\">65</span>，<span class=\"gk-math\" data-tex=\"70\">70</span>，<span class=\"gk-math\" data-tex=\"75\">75</span>，<span class=\"gk-math\" data-tex=\"80\">80</span>，<span class=\"gk-math\" data-tex=\"85\">85</span>，<span class=\"gk-math\" data-tex=\"90\">90</span>，<span class=\"gk-math\" data-tex=\"95\">95</span>，中位数为 <span class=\"gk-math\" data-tex=\"72.5&gt;70\">72.5&gt;70</span>，A 错误. 讲座前数据较为分散，其标准差大于讲座后数据，C 错误. 讲座前极差为 <span class=\"gk-math\" data-tex=\"95-60=35\">95-60=35</span>，讲座后极差为 <span class=\"gk-math\" data-tex=\"100-80=20\">100-80=20</span>，前者更大，D 错误. 答案为 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q03","paperId":"2022-national_paper_a_liberal","number":3,"type":"single","score":5,"lessonIds":["7.2","7.1"],"difficulty":"基础","hint":"先写出共轭复数 1−i，再分别算 iz 和 3z̄。","legacy":false,"legacyReason":"","searchText":"若 z=1+\\i ，则 \\left|\\i z+3\\overline{z}\\right|= （ ） 4\\sqrt{5} 4\\sqrt{2} 2\\sqrt{5} 2\\sqrt{2}","questionHtml":"若 <span class=\"gk-math\" data-tex=\"z=1+\\i\">z=1+\\i</span>，则 <span class=\"gk-math\" data-tex=\"\\left|\\i z+3\\overline{z}\\right|=\">\\left|\\i z+3\\overline{z}\\right|=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"4\\sqrt{5}\">4\\sqrt{5}</span>","<span class=\"gk-math\" data-tex=\"4\\sqrt{2}\">4\\sqrt{2}</span>","<span class=\"gk-math\" data-tex=\"2\\sqrt{5}\">2\\sqrt{5}</span>","<span class=\"gk-math\" data-tex=\"2\\sqrt{2}\">2\\sqrt{2}</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\overline{z}=1-\\i\">\\overline{z}=1-\\i</span>，所以 <span class=\"gk-math\" data-tex=\"\\i z+3\\overline{z}=\\i(1+\\i)+3(1-\\i)=-1+\\i+3-3\\i=2-2\\i\">\\i z+3\\overline{z}=\\i(1+\\i)+3(1-\\i)=-1+\\i+3-3\\i=2-2\\i</span>，故 <span class=\"gk-math\" data-tex=\"\\left|\\i z+3\\overline{z}\\right|=\\sqrt{2^2+(-2)^2}=2\\sqrt2\">\\left|\\i z+3\\overline{z}\\right|=\\sqrt{2^2+(-2)^2}=2\\sqrt2</span>，答案为 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q04","paperId":"2022-national_paper_a_liberal","number":4,"type":"single","score":5,"lessonIds":["8.2","8.3"],"difficulty":"进阶","hint":"这是旧课标三视图题，超出当前五册；先由三个视图还原几何体，再分块求体积。","legacy":true,"legacyReason":"","searchText":"如图，网格纸上绘制的是一个多面体的三视图，网格小正方形的边长为 1 ，则该多面体的体积为（ ） 8 12 16 20","questionHtml":"如图，网格纸上绘制的是一个多面体的三视图，网格小正方形的边长为 <span class=\"gk-math\" data-tex=\"1\">1</span>，则该多面体的体积为（ ）<br><br> <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,178px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q4_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q4_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"162\" height=\"126\" style=\"aspect-ratio:162/126;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["8","12","16","20"],"answerHtml":"B","answerKey":"B","solutionHtml":"由正视图知该多面体是底面为直角梯形的直棱柱，该梯形上、下底边长分别为 <span class=\"gk-math\" data-tex=\"2\">2</span> 和 <span class=\"gk-math\" data-tex=\"4\">4</span>，高为 <span class=\"gk-math\" data-tex=\"2\">2</span>，其面积为 <span class=\"gk-math\" data-tex=\"\\dfrac{2+4}{2}\\times2=6\">\\dfrac{2+4}{2}\\times2=6</span>；由侧视图知其高为 <span class=\"gk-math\" data-tex=\"2\">2</span>. 所以该多面体的体积为 <span class=\"gk-math\" data-tex=\"6\\times2=12\">6\\times2=12</span>，答案为 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q05","paperId":"2022-national_paper_a_liberal","number":5,"type":"single","score":5,"lessonIds":["5.6","5.4"],"difficulty":"进阶","hint":"向左平移就是把 x 换成 x+π/2；再让新的正弦函数成为偶函数。","legacy":false,"legacyReason":"","searchText":"将函数 f(x)=\\sin\\left(\\omega x+\\dfrac{\\pi}{3}\\right) （ \\omega>0 ）的图像向左平移 \\dfrac{\\pi}{2} 个单位长度后得到曲线 C ，若 C 关于 y 轴对称，则 \\omega 的最小值是（ ） \\dfrac{1}{6} \\dfrac{1}{4} \\dfrac{1}{3} \\dfrac{1}{2}","questionHtml":"将函数 <span class=\"gk-math\" data-tex=\"f(x)=\\sin\\left(\\omega x+\\dfrac{\\pi}{3}\\right)\">f(x)=\\sin\\left(\\omega x+\\dfrac{\\pi}{3}\\right)</span>（<span class=\"gk-math\" data-tex=\"\\omega&gt;0\">\\omega&gt;0</span>）的图像向左平移 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{2}\">\\dfrac{\\pi}{2}</span> 个单位长度后得到曲线 <span class=\"gk-math\" data-tex=\"C\">C</span>，若 <span class=\"gk-math\" data-tex=\"C\">C</span> 关于 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴对称，则 <span class=\"gk-math\" data-tex=\"\\omega\">\\omega</span> 的最小值是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{1}{6}\">\\dfrac{1}{6}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{1}{4}\">\\dfrac{1}{4}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{1}{3}\">\\dfrac{1}{3}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{1}{2}\">\\dfrac{1}{2}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"图像向左平移 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{2}\">\\dfrac{\\pi}{2}</span> 个单位长度后得到曲线 <span class=\"gk-math\" data-tex=\"C:y=\\sin\\left(\\omega x+\\dfrac{\\omega\\pi}{2}+\\dfrac{\\pi}{3}\\right)\">C:y=\\sin\\left(\\omega x+\\dfrac{\\omega\\pi}{2}+\\dfrac{\\pi}{3}\\right)</span>. 曲线 <span class=\"gk-math\" data-tex=\"C\">C</span> 关于 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴对称，说明它是偶函数，所以 <span class=\"gk-math\" data-tex=\"\\dfrac{\\omega\\pi}{2}+\\dfrac{\\pi}{3}=\\dfrac{\\pi}{2}+k\\pi\">\\dfrac{\\omega\\pi}{2}+\\dfrac{\\pi}{3}=\\dfrac{\\pi}{2}+k\\pi</span>（<span class=\"gk-math\" data-tex=\"k\\in\\Z\">k\\in\\Z</span>），解得 <span class=\"gk-math\" data-tex=\"\\omega=\\dfrac13+2k\">\\omega=\\dfrac13+2k</span>. 又 <span class=\"gk-math\" data-tex=\"\\omega&gt;0\">\\omega&gt;0</span>，取 <span class=\"gk-math\" data-tex=\"k=0\">k=0</span> 得 <span class=\"gk-math\" data-tex=\"\\omega\">\\omega</span> 的最小值为 <span class=\"gk-math\" data-tex=\"\\dfrac13\">\\dfrac13</span>，答案为 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q06","paperId":"2022-national_paper_a_liberal","number":6,"type":"single","score":5,"lessonIds":["10.1","e3-6.2"],"difficulty":"基础","hint":"先列出从六张卡片中选两张的全部组合，再数乘积能被 4 整除的组合。","legacy":false,"legacyReason":"","searchText":"从分别写有 1 ， 2 ， 3 ， 4 ， 5 ， 6 的 6 张卡片中无放回随机抽取 2 张，则抽到的 2 张卡片上的数字之积是 4 的倍数的概率为（ ） \\dfrac{1}{5} \\dfrac{1}{3} \\dfrac{2}{5} \\dfrac{2}{3}","questionHtml":"从分别写有 <span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"6\">6</span> 的 <span class=\"gk-math\" data-tex=\"6\">6</span> 张卡片中无放回随机抽取 <span class=\"gk-math\" data-tex=\"2\">2</span> 张，则抽到的 <span class=\"gk-math\" data-tex=\"2\">2</span> 张卡片上的数字之积是 <span class=\"gk-math\" data-tex=\"4\">4</span> 的倍数的概率为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{1}{5}\">\\dfrac{1}{5}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{1}{3}\">\\dfrac{1}{3}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{2}{5}\">\\dfrac{2}{5}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{2}{3}\">\\dfrac{2}{3}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"从 <span class=\"gk-math\" data-tex=\"6\">6</span> 张卡片中抽取 <span class=\"gk-math\" data-tex=\"2\">2</span> 张共有 <span class=\"gk-math\" data-tex=\"\\mathrm C_6^2=15\">\\mathrm C_6^2=15</span> 种等可能结果. 两数之积为 <span class=\"gk-math\" data-tex=\"4\">4</span> 的倍数，可分为两类：含有 <span class=\"gk-math\" data-tex=\"4\">4</span> 的抽取，此时 <span class=\"gk-math\" data-tex=\"4\">4</span> 与其余 <span class=\"gk-math\" data-tex=\"5\">5</span> 个数中任意一个的积都是 <span class=\"gk-math\" data-tex=\"4\">4</span> 的倍数，共 <span class=\"gk-math\" data-tex=\"5\">5</span> 种；不含有 <span class=\"gk-math\" data-tex=\"4\">4</span> 时，只有同时抽到 <span class=\"gk-math\" data-tex=\"2\">2</span> 和 <span class=\"gk-math\" data-tex=\"6\">6</span>，其积 <span class=\"gk-math\" data-tex=\"12\">12</span> 为 <span class=\"gk-math\" data-tex=\"4\">4</span> 的倍数，共 <span class=\"gk-math\" data-tex=\"1\">1</span> 种. 所以所求概率为 <span class=\"gk-math\" data-tex=\"\\dfrac{5+1}{15}=\\dfrac25\">\\dfrac{5+1}{15}=\\dfrac25</span>，答案为 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q07","paperId":"2022-national_paper_a_liberal","number":7,"type":"single","score":5,"lessonIds":["3.2","4.2","5.4"],"difficulty":"进阶","hint":"先判断整个函数的奇偶性，再看 0<x<π/2 时函数值的正负。","legacy":false,"legacyReason":"","searchText":"函数 y=\\left(3^x-3^{-x}\\right)\\cos x 在区间 \\left[-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right] 的图象大致为（ ） ","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\left(3^x-3^{-x}\\right)\\cos x\">y=\\left(3^x-3^{-x}\\right)\\cos x</span> 在区间 <span class=\"gk-math\" data-tex=\"\\left[-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right]\">\\left[-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right]</span> 的图象大致为（ ）","optionsHtml":["<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,341px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optA.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optA.webp\" alt=\"高考题图，点击可放大\" width=\"325\" height=\"340\" style=\"aspect-ratio:325/340;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,361px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optB.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optB.webp\" alt=\"高考题图，点击可放大\" width=\"345\" height=\"340\" style=\"aspect-ratio:345/340;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,341px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optC.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optC.webp\" alt=\"高考题图，点击可放大\" width=\"325\" height=\"360\" style=\"aspect-ratio:325/360;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,361px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optD.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q7_optD.webp\" alt=\"高考题图，点击可放大\" width=\"345\" height=\"360\" style=\"aspect-ratio:345/360;width:100%\" loading=\"lazy\"></button></figure>"],"answerHtml":"A","answerKey":"A","solutionHtml":"记 <span class=\"gk-math\" data-tex=\"g(x)=3^x-3^{-x}\">g(x)=3^x-3^{-x}</span>，它是奇函数且在 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 上单调递增；<span class=\"gk-math\" data-tex=\"\\cos x\">\\cos x</span> 是偶函数，在 <span class=\"gk-math\" data-tex=\"\\left[-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right]\">\\left[-\\dfrac{\\pi}{2},\\dfrac{\\pi}{2}\\right]</span> 上非负. 所以原函数是奇函数，图象关于原点对称，且当 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 时 <span class=\"gk-math\" data-tex=\"y=0\">y=0</span>. 当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 且较小时，<span class=\"gk-math\" data-tex=\"g(x)&gt;0\">g(x)&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\cos x&gt;0\">\\cos x&gt;0</span>，函数值为正；当 <span class=\"gk-math\" data-tex=\"x\\to\\dfrac{\\pi}{2}\">x\\to\\dfrac{\\pi}{2}</span> 时 <span class=\"gk-math\" data-tex=\"\\cos x\\to0\">\\cos x\\to0</span>，函数值趋于 <span class=\"gk-math\" data-tex=\"0\">0</span>. 符合这些特征的只有选项 A，答案为 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q08","paperId":"2022-national_paper_a_liberal","number":8,"type":"single","score":5,"lessonIds":["e2-5.2","e2-5.3"],"difficulty":"进阶","hint":"先用 f(1)=−2 求 b，再用极值点处 f′(1)=0 求 a。","legacy":false,"legacyReason":"","searchText":"当 x=1 时，函数 f(x)=a\\ln x+\\dfrac{b}{x} 取得最大值 -2 ，则 f'(2)= （ ） -1 -\\dfrac{1}{2} \\dfrac{1}{2} 1","questionHtml":"当 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 时，函数 <span class=\"gk-math\" data-tex=\"f(x)=a\\ln x+\\dfrac{b}{x}\">f(x)=a\\ln x+\\dfrac{b}{x}</span> 取得最大值 <span class=\"gk-math\" data-tex=\"-2\">-2</span>，则 <span class=\"gk-math\" data-tex=\"f&#x27;(2)=\">f&#x27;(2)=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-1\">-1</span>","<span class=\"gk-math\" data-tex=\"-\\dfrac{1}{2}\">-\\dfrac{1}{2}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{1}{2}\">\\dfrac{1}{2}</span>","1"],"answerHtml":"B","answerKey":"B","solutionHtml":"<span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\dfrac ax-\\dfrac b{x^2}\">f&#x27;(x)=\\dfrac ax-\\dfrac b{x^2}</span>. 由 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 是极大值点且 <span class=\"gk-math\" data-tex=\"f(1)=-2\">f(1)=-2</span> 得 <span class=\"gk-math\" data-tex=\"f(1)=b=-2\">f(1)=b=-2</span>，<span class=\"gk-math\" data-tex=\"f&#x27;(1)=a-b=0\">f&#x27;(1)=a-b=0</span>，所以 <span class=\"gk-math\" data-tex=\"a=b=-2\">a=b=-2</span>. 于是 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=-\\dfrac2x+\\dfrac2{x^2}\">f&#x27;(x)=-\\dfrac2x+\\dfrac2{x^2}</span>，<span class=\"gk-math\" data-tex=\"f&#x27;(2)=-1+\\dfrac12=-\\dfrac12\">f&#x27;(2)=-1+\\dfrac12=-\\dfrac12</span>，答案为 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q09","paperId":"2022-national_paper_a_liberal","number":9,"type":"single","score":5,"lessonIds":["8.6","e1-1.4"],"difficulty":"进阶","hint":"把体对角线向两个已知平面作投影，用两次 sin30° 写出棱长关系。","legacy":false,"legacyReason":"","searchText":"在长方体 ABCD-A_1B_1C_1D_1 中，已知 B_1D 与平面 ABCD 和平面 AA_1B_1B 所成的角均为 30^\\circ ，则（ ） AB=2AD AB 与平面 AB_1C_1D 所成的角为 30^\\circ AC=CB_1 B_1D 与平面 BB_1C_1C 所成的角为 45^\\circ","questionHtml":"在长方体 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 中，已知 <span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 与平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 和平面 <span class=\"gk-math\" data-tex=\"AA_1B_1B\">AA_1B_1B</span> 所成的角均为 <span class=\"gk-math\" data-tex=\"30^\\circ\">30^\\circ</span>，则（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,394px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q9_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q9_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"378\" height=\"376\" style=\"aspect-ratio:378/376;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["<span class=\"gk-math\" data-tex=\"AB=2AD\">AB=2AD</span>","<span class=\"gk-math\" data-tex=\"AB\">AB</span> 与平面 <span class=\"gk-math\" data-tex=\"AB_1C_1D\">AB_1C_1D</span> 所成的角为 <span class=\"gk-math\" data-tex=\"30^\\circ\">30^\\circ</span>","<span class=\"gk-math\" data-tex=\"AC=CB_1\">AC=CB_1</span>","<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 与平面 <span class=\"gk-math\" data-tex=\"BB_1C_1C\">BB_1C_1C</span> 所成的角为 <span class=\"gk-math\" data-tex=\"45^\\circ\">45^\\circ</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"AB=a\">AB=a</span>，<span class=\"gk-math\" data-tex=\"AD=b\">AD=b</span>，<span class=\"gk-math\" data-tex=\"AA_1=c\">AA_1=c</span>. <span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 与平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 所成角为 <span class=\"gk-math\" data-tex=\"\\angle B_1DB\">\\angle B_1DB</span>，所以 <span class=\"gk-math\" data-tex=\"\\tan\\angle B_1DB=\\dfrac{c}{BD}=\\dfrac{c}{\\sqrt{a^2+b^2}}=\\tan30^\\circ\">\\tan\\angle B_1DB=\\dfrac{c}{BD}=\\dfrac{c}{\\sqrt{a^2+b^2}}=\\tan30^\\circ</span>，得 <span class=\"gk-math\" data-tex=\"a^2+b^2=3c^2\">a^2+b^2=3c^2</span>. 又 <span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 与平面 <span class=\"gk-math\" data-tex=\"AA_1B_1B\">AA_1B_1B</span> 所成角的正弦为 <span class=\"gk-math\" data-tex=\"\\dfrac{b}{\\sqrt{a^2+b^2+c^2}}=\\dfrac12\">\\dfrac{b}{\\sqrt{a^2+b^2+c^2}}=\\dfrac12</span>，得 <span class=\"gk-math\" data-tex=\"a^2+c^2=3b^2\">a^2+c^2=3b^2</span>. 两式相减得 <span class=\"gk-math\" data-tex=\"b^2-c^2=3c^2-3b^2\">b^2-c^2=3c^2-3b^2</span>，即 <span class=\"gk-math\" data-tex=\"b=c\">b=c</span>，从而 <span class=\"gk-math\" data-tex=\"a^2=2c^2\">a^2=2c^2</span>，即 <span class=\"gk-math\" data-tex=\"a=\\sqrt2c\">a=\\sqrt2c</span>，<span class=\"gk-math\" data-tex=\"b=c\">b=c</span>.<br><br>于是 <span class=\"gk-math\" data-tex=\"AB=\\sqrt2c\">AB=\\sqrt2c</span>，<span class=\"gk-math\" data-tex=\"AD=c\">AD=c</span>，<span class=\"gk-math\" data-tex=\"AB=\\sqrt2AD\\ne2AD\">AB=\\sqrt2AD\\ne2AD</span>，A 错误；<span class=\"gk-math\" data-tex=\"AB\">AB</span> 与平面 <span class=\"gk-math\" data-tex=\"AB_1C_1D\">AB_1C_1D</span> 所成角的正弦为 <span class=\"gk-math\" data-tex=\"\\dfrac{c}{\\sqrt{a^2+c^2}}=\\dfrac{c}{\\sqrt3c}=\\dfrac{\\sqrt3}3\\ne\\sin30^\\circ\">\\dfrac{c}{\\sqrt{a^2+c^2}}=\\dfrac{c}{\\sqrt3c}=\\dfrac{\\sqrt3}3\\ne\\sin30^\\circ</span>，B 错误；<span class=\"gk-math\" data-tex=\"AC=\\sqrt{a^2+b^2}=\\sqrt3c\">AC=\\sqrt{a^2+b^2}=\\sqrt3c</span>，<span class=\"gk-math\" data-tex=\"CB_1=\\sqrt{b^2+c^2}=\\sqrt2c\">CB_1=\\sqrt{b^2+c^2}=\\sqrt2c</span>，二者不等，C 错误；<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 与平面 <span class=\"gk-math\" data-tex=\"BB_1C_1C\">BB_1C_1C</span> 所成角的正弦为 <span class=\"gk-math\" data-tex=\"\\dfrac{AB}{B_1D}=\\dfrac{\\sqrt2c}{2c}=\\dfrac{\\sqrt2}2\">\\dfrac{AB}{B_1D}=\\dfrac{\\sqrt2c}{2c}=\\dfrac{\\sqrt2}2</span>，所以所成角为 <span class=\"gk-math\" data-tex=\"45^\\circ\">45^\\circ</span>，D 正确. 答案为 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q10","paperId":"2022-national_paper_a_liberal","number":10,"type":"single","score":5,"lessonIds":["8.3","5.1"],"difficulty":"进阶","hint":"共同母线设为 l，先用侧面积比求底面半径比，再用展开扇形的弧长求半径之和。","legacy":false,"legacyReason":"","searchText":"甲，乙两个圆锥的母线长相等，侧面展开图的圆心角之和为 2\\pi ，侧面积分别为 S_{\\text{甲}} 和 S_{\\text{乙}} ，体积分别为 V_{\\text{甲}} 和 V_{\\text{乙}} . 若 \\dfrac{S_{\\text{甲}}}{S_{\\text{乙}}}=2 ，则 \\dfrac{V_{\\text{甲}}}{V_{\\text{乙}}}= （ ） \\sqrt{5} 2\\sqrt{2} \\sqrt{10} \\dfrac{5\\sqrt{10}}{4}","questionHtml":"甲，乙两个圆锥的母线长相等，侧面展开图的圆心角之和为 <span class=\"gk-math\" data-tex=\"2\\pi\">2\\pi</span>，侧面积分别为 <span class=\"gk-math\" data-tex=\"S_{\\text{甲}}\">S_{\\text{甲}}</span> 和 <span class=\"gk-math\" data-tex=\"S_{\\text{乙}}\">S_{\\text{乙}}</span>，体积分别为 <span class=\"gk-math\" data-tex=\"V_{\\text{甲}}\">V_{\\text{甲}}</span> 和 <span class=\"gk-math\" data-tex=\"V_{\\text{乙}}\">V_{\\text{乙}}</span>. 若 <span class=\"gk-math\" data-tex=\"\\dfrac{S_{\\text{甲}}}{S_{\\text{乙}}}=2\">\\dfrac{S_{\\text{甲}}}{S_{\\text{乙}}}=2</span>，则 <span class=\"gk-math\" data-tex=\"\\dfrac{V_{\\text{甲}}}{V_{\\text{乙}}}=\">\\dfrac{V_{\\text{甲}}}{V_{\\text{乙}}}=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\sqrt{5}\">\\sqrt{5}</span>","<span class=\"gk-math\" data-tex=\"2\\sqrt{2}\">2\\sqrt{2}</span>","<span class=\"gk-math\" data-tex=\"\\sqrt{10}\">\\sqrt{10}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{5\\sqrt{10}}{4}\">\\dfrac{5\\sqrt{10}}{4}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"设两圆锥母线长均为 <span class=\"gk-math\" data-tex=\"l\">l</span>，底面半径分别为 <span class=\"gk-math\" data-tex=\"r_1\">r_1</span>，<span class=\"gk-math\" data-tex=\"r_2\">r_2</span>. 侧面积 <span class=\"gk-math\" data-tex=\"S=\\pi rl\">S=\\pi rl</span>，由 <span class=\"gk-math\" data-tex=\"\\dfrac{S_{\\text{甲}}}{S_{\\text{乙}}}=2\">\\dfrac{S_{\\text{甲}}}{S_{\\text{乙}}}=2</span> 得 <span class=\"gk-math\" data-tex=\"r_1=2r_2\">r_1=2r_2</span>. 侧面展开图圆心角为 <span class=\"gk-math\" data-tex=\"\\dfrac{2\\pi r}{l}\">\\dfrac{2\\pi r}{l}</span>，由圆心角之和为 <span class=\"gk-math\" data-tex=\"2\\pi\">2\\pi</span> 得 <span class=\"gk-math\" data-tex=\"\\dfrac{2\\pi r_1}{l}+\\dfrac{2\\pi r_2}{l}=2\\pi\">\\dfrac{2\\pi r_1}{l}+\\dfrac{2\\pi r_2}{l}=2\\pi</span>，即 <span class=\"gk-math\" data-tex=\"r_1+r_2=l\">r_1+r_2=l</span>，所以 <span class=\"gk-math\" data-tex=\"l=3r_2\">l=3r_2</span>.<br><br>两圆锥的高分别为 <span class=\"gk-math\" data-tex=\"h_1=\\sqrt{l^2-r_1^2}=\\sqrt{9-4}\\,r_2=\\sqrt5\\,r_2\">h_1=\\sqrt{l^2-r_1^2}=\\sqrt{9-4}\\,r_2=\\sqrt5\\,r_2</span>，<span class=\"gk-math\" data-tex=\"h_2=\\sqrt{l^2-r_2^2}=\\sqrt{9-1}\\,r_2=2\\sqrt2\\,r_2\">h_2=\\sqrt{l^2-r_2^2}=\\sqrt{9-1}\\,r_2=2\\sqrt2\\,r_2</span>. 体积 <span class=\"gk-math\" data-tex=\"V=\\dfrac13\\pi r^2h\">V=\\dfrac13\\pi r^2h</span>，所以 <span class=\"gk-math\" data-tex=\"\\dfrac{V_{\\text{甲}}}{V_{\\text{乙}}}=\\dfrac{r_1^2h_1}{r_2^2h_2}=\\dfrac{4\\sqrt5}{2\\sqrt2}=\\sqrt{10}\">\\dfrac{V_{\\text{甲}}}{V_{\\text{乙}}}=\\dfrac{r_1^2h_1}{r_2^2h_2}=\\dfrac{4\\sqrt5}{2\\sqrt2}=\\sqrt{10}</span>，答案为 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q11","paperId":"2022-national_paper_a_liberal","number":11,"type":"single","score":5,"lessonIds":["e1-3.1","6.3"],"difficulty":"进阶","hint":"写出三个顶点的坐标，把向量数量积化成 b²−a²，再结合 c/a=1/3。","legacy":false,"legacyReason":"","searchText":"已知椭圆 C:\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1 （ a>b>0 ）的离心率为 \\dfrac{1}{3} ， A_1 ， A_2 分别为 C 的左，右顶点， B 为 C 的上顶点. 若 \\overrightarrow{BA_1}\\cdot\\overrightarrow{BA_2}=-1 ，则 C 的方程为（ ） \\dfrac{x^2}{18}+\\dfrac{y^2}{16}=1 \\dfrac{x^2}{9}+\\dfrac{y^2}{8}=1 \\dfrac{x^2}{3}+\\dfrac{y^2}{2}=1 \\dfrac{x^2}{2}+y^2=1","questionHtml":"已知椭圆 <span class=\"gk-math\" data-tex=\"C:\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1\">C:\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>）的离心率为 <span class=\"gk-math\" data-tex=\"\\dfrac{1}{3}\">\\dfrac{1}{3}</span>，<span class=\"gk-math\" data-tex=\"A_1\">A_1</span>，<span class=\"gk-math\" data-tex=\"A_2\">A_2</span> 分别为 <span class=\"gk-math\" data-tex=\"C\">C</span> 的左，右顶点，<span class=\"gk-math\" data-tex=\"B\">B</span> 为 <span class=\"gk-math\" data-tex=\"C\">C</span> 的上顶点. 若 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BA_1}\\cdot\\overrightarrow{BA_2}=-1\">\\overrightarrow{BA_1}\\cdot\\overrightarrow{BA_2}=-1</span>，则 <span class=\"gk-math\" data-tex=\"C\">C</span> 的方程为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{18}+\\dfrac{y^2}{16}=1\">\\dfrac{x^2}{18}+\\dfrac{y^2}{16}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{9}+\\dfrac{y^2}{8}=1\">\\dfrac{x^2}{9}+\\dfrac{y^2}{8}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{3}+\\dfrac{y^2}{2}=1\">\\dfrac{x^2}{3}+\\dfrac{y^2}{2}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{2}+y^2=1\">\\dfrac{x^2}{2}+y^2=1</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"<span class=\"gk-math\" data-tex=\"A_1(-a,0)\">A_1(-a,0)</span>，<span class=\"gk-math\" data-tex=\"A_2(a,0)\">A_2(a,0)</span>，<span class=\"gk-math\" data-tex=\"B(0,b)\">B(0,b)</span>，所以 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BA_1}=(-a,-b)\">\\overrightarrow{BA_1}=(-a,-b)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{BA_2}=(a,-b)\">\\overrightarrow{BA_2}=(a,-b)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{BA_1}\\cdot\\overrightarrow{BA_2}=-a^2+b^2=-1\">\\overrightarrow{BA_1}\\cdot\\overrightarrow{BA_2}=-a^2+b^2=-1</span>，即 <span class=\"gk-math\" data-tex=\"a^2-b^2=1\">a^2-b^2=1</span>. 又离心率 <span class=\"gk-math\" data-tex=\"e=\\dfrac ca=\\dfrac13\">e=\\dfrac ca=\\dfrac13</span>，所以 <span class=\"gk-math\" data-tex=\"c^2=\\dfrac{a^2}9\">c^2=\\dfrac{a^2}9</span>，<span class=\"gk-math\" data-tex=\"b^2=a^2-c^2=\\dfrac{8a^2}9\">b^2=a^2-c^2=\\dfrac{8a^2}9</span>. 代入 <span class=\"gk-math\" data-tex=\"a^2-b^2=1\">a^2-b^2=1</span> 得 <span class=\"gk-math\" data-tex=\"a^2-\\dfrac{8a^2}9=\\dfrac{a^2}9=1\">a^2-\\dfrac{8a^2}9=\\dfrac{a^2}9=1</span>，所以 <span class=\"gk-math\" data-tex=\"a^2=9\">a^2=9</span>，<span class=\"gk-math\" data-tex=\"b^2=8\">b^2=8</span>，椭圆方程为 <span class=\"gk-math\" data-tex=\"\\dfrac{x^2}9+\\dfrac{y^2}8=1\">\\dfrac{x^2}9+\\dfrac{y^2}8=1</span>，答案为 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q12","paperId":"2022-national_paper_a_liberal","number":12,"type":"single","score":5,"lessonIds":["4.2","e2-5.3"],"difficulty":"挑战","hint":"由 9^m=10 先判断 m>1，再研究 t^m 在 8、9、10 附近的增长快慢。","legacy":false,"legacyReason":"","searchText":"已知 9^m=10 ， a=10^m-11 ， b=8^m-9 ，则（ ） a>0>b a>b>0 b>a>0 b>0>a","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"9^m=10\">9^m=10</span>，<span class=\"gk-math\" data-tex=\"a=10^m-11\">a=10^m-11</span>，<span class=\"gk-math\" data-tex=\"b=8^m-9\">b=8^m-9</span>，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a&gt;0&gt;b\">a&gt;0&gt;b</span>","<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>","<span class=\"gk-math\" data-tex=\"b&gt;a&gt;0\">b&gt;a&gt;0</span>","<span class=\"gk-math\" data-tex=\"b&gt;0&gt;a\">b&gt;0&gt;a</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"9^m=10\">9^m=10</span> 得 <span class=\"gk-math\" data-tex=\"m=\\log_{9}10=\\dfrac{\\ln10}{\\ln9}&gt;1\">m=\\log_{9}10=\\dfrac{\\ln10}{\\ln9}&gt;1</span>.<br><br>先判断 <span class=\"gk-math\" data-tex=\"a=10^m-11\">a=10^m-11</span> 的符号. <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span> 等价于 <span class=\"gk-math\" data-tex=\"10^m&gt;11\">10^m&gt;11</span>，即 <span class=\"gk-math\" data-tex=\"m&gt;\\log_{10}11=\\dfrac{\\ln11}{\\ln10}\">m&gt;\\log_{10}11=\\dfrac{\\ln11}{\\ln10}</span>，也即 <span class=\"gk-math\" data-tex=\"\\dfrac{\\ln10}{\\ln9}&gt;\\dfrac{\\ln11}{\\ln10}\">\\dfrac{\\ln10}{\\ln9}&gt;\\dfrac{\\ln11}{\\ln10}</span>，等价于 <span class=\"gk-math\" data-tex=\"(\\ln10)^2&gt;\\ln9\\ln11\">(\\ln10)^2&gt;\\ln9\\ln11</span>. 而 <span class=\"gk-math\" data-tex=\"\\ln9\\ln11=\\left(\\ln10+\\ln\\dfrac9{10}\\right)\\left(\\ln10+\\ln\\dfrac{11}{10}\\right)=(\\ln10)^2+\\ln10\\left(\\ln\\dfrac9{10}+\\ln\\dfrac{11}{10}\\right)+\\ln\\dfrac9{10}\\ln\\dfrac{11}{10}\">\\ln9\\ln11=\\left(\\ln10+\\ln\\dfrac9{10}\\right)\\left(\\ln10+\\ln\\dfrac{11}{10}\\right)=(\\ln10)^2+\\ln10\\left(\\ln\\dfrac9{10}+\\ln\\dfrac{11}{10}\\right)+\\ln\\dfrac9{10}\\ln\\dfrac{11}{10}</span>. 因为 <span class=\"gk-math\" data-tex=\"\\ln\\dfrac9{10}&lt;0\">\\ln\\dfrac9{10}&lt;0</span>，<span class=\"gk-math\" data-tex=\"\\ln\\dfrac{11}{10}&gt;0\">\\ln\\dfrac{11}{10}&gt;0</span> 且 <span class=\"gk-math\" data-tex=\"\\ln\\dfrac9{10}+\\ln\\dfrac{11}{10}=\\ln\\dfrac{99}{100}&lt;0\">\\ln\\dfrac9{10}+\\ln\\dfrac{11}{10}=\\ln\\dfrac{99}{100}&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"\\ln9\\ln11&lt;(\\ln10)^2\">\\ln9\\ln11&lt;(\\ln10)^2</span>，从而 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>.<br><br>再判断 <span class=\"gk-math\" data-tex=\"b=8^m-9\">b=8^m-9</span> 的符号. <span class=\"gk-math\" data-tex=\"b&lt;0\">b&lt;0</span> 等价于 <span class=\"gk-math\" data-tex=\"8^m&lt;9\">8^m&lt;9</span>，即 <span class=\"gk-math\" data-tex=\"m&lt;\\log_8 9=\\dfrac{\\ln9}{\\ln8}\">m&lt;\\log_8 9=\\dfrac{\\ln9}{\\ln8}</span>，也即 <span class=\"gk-math\" data-tex=\"\\dfrac{\\ln10}{\\ln9}&lt;\\dfrac{\\ln9}{\\ln8}\">\\dfrac{\\ln10}{\\ln9}&lt;\\dfrac{\\ln9}{\\ln8}</span>，等价于 <span class=\"gk-math\" data-tex=\"\\ln10\\ln8&lt;(\\ln9)^2\">\\ln10\\ln8&lt;(\\ln9)^2</span>. 而 <span class=\"gk-math\" data-tex=\"\\ln10\\ln8=\\left(\\ln9+\\ln\\dfrac{10}{9}\\right)\\left(\\ln9+\\ln\\dfrac89\\right)=(\\ln9)^2+\\ln9\\left(\\ln\\dfrac{10}{9}+\\ln\\dfrac89\\right)+\\ln\\dfrac{10}{9}\\ln\\dfrac89\">\\ln10\\ln8=\\left(\\ln9+\\ln\\dfrac{10}{9}\\right)\\left(\\ln9+\\ln\\dfrac89\\right)=(\\ln9)^2+\\ln9\\left(\\ln\\dfrac{10}{9}+\\ln\\dfrac89\\right)+\\ln\\dfrac{10}{9}\\ln\\dfrac89</span>. 因为 <span class=\"gk-math\" data-tex=\"\\ln\\dfrac{10}{9}&gt;0\">\\ln\\dfrac{10}{9}&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\ln\\dfrac89&lt;0\">\\ln\\dfrac89&lt;0</span> 且 <span class=\"gk-math\" data-tex=\"\\ln\\dfrac{10}{9}+\\ln\\dfrac89=\\ln\\dfrac{80}{81}&lt;0\">\\ln\\dfrac{10}{9}+\\ln\\dfrac89=\\ln\\dfrac{80}{81}&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"\\ln10\\ln8&lt;(\\ln9)^2\">\\ln10\\ln8&lt;(\\ln9)^2</span>，从而 <span class=\"gk-math\" data-tex=\"b&lt;0\">b&lt;0</span>.<br><br>因此 <span class=\"gk-math\" data-tex=\"a&gt;0&gt;b\">a&gt;0&gt;b</span>，答案为 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q13","paperId":"2022-national_paper_a_liberal","number":13,"type":"fill","score":5,"lessonIds":["6.3"],"difficulty":"基础","hint":"两个坐标向量垂直时数量积为零，直接列出 m+3(m+1)=0。","legacy":false,"legacyReason":"","searchText":"已知向量 \\bs a=\\left(m,3\\right) ， \\bs b=\\left(1,m+1\\right) . 若 \\bs a\\perp\\bs b ，则 m= ________ . ","questionHtml":"已知向量 <span class=\"gk-math\" data-tex=\"\\bs a=\\left(m,3\\right)\">\\bs a=\\left(m,3\\right)</span>，<span class=\"gk-math\" data-tex=\"\\bs b=\\left(1,m+1\\right)\">\\bs b=\\left(1,m+1\\right)</span>. 若 <span class=\"gk-math\" data-tex=\"\\bs a\\perp\\bs b\">\\bs a\\perp\\bs b</span>，则 <span class=\"gk-math\" data-tex=\"m=\">m=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"-\\dfrac{3}{4}\">-\\dfrac{3}{4}</span>","answerKey":"","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\bs a\\perp\\bs b\">\\bs a\\perp\\bs b</span> 得 <span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs b=m+3(m+1)=4m+3=0\">\\bs a\\cdot\\bs b=m+3(m+1)=4m+3=0</span>，解得 <span class=\"gk-math\" data-tex=\"m=-\\dfrac34\">m=-\\dfrac34</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q14","paperId":"2022-national_paper_a_liberal","number":14,"type":"fill","score":5,"lessonIds":["e1-2.4","e1-2.3"],"difficulty":"基础","hint":"设圆心为 (u,v)，用圆心在已知直线上和到两个已知点等距列方程。","legacy":false,"legacyReason":"","searchText":"设圆 M 的圆心在直线 2x+y-1=0 上，点 \\left(3,0\\right) 和 \\left(0,1\\right) 均在圆 M 上，则圆 M 的方程为 ________ . ","questionHtml":"设圆 <span class=\"gk-math\" data-tex=\"M\">M</span> 的圆心在直线 <span class=\"gk-math\" data-tex=\"2x+y-1=0\">2x+y-1=0</span> 上，点 <span class=\"gk-math\" data-tex=\"\\left(3,0\\right)\">\\left(3,0\\right)</span> 和 <span class=\"gk-math\" data-tex=\"\\left(0,1\\right)\">\\left(0,1\\right)</span> 均在圆 <span class=\"gk-math\" data-tex=\"M\">M</span> 上，则圆 <span class=\"gk-math\" data-tex=\"M\">M</span> 的方程为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"(x-1)^2+(y+1)^2=5\">(x-1)^2+(y+1)^2=5</span>","answerKey":"","solutionHtml":"设圆心 <span class=\"gk-math\" data-tex=\"M(h,k)\">M(h,k)</span>，由圆心在直线上得 <span class=\"gk-math\" data-tex=\"2h+k=1\">2h+k=1</span>. 由点 <span class=\"gk-math\" data-tex=\"(3,0)\">(3,0)</span> 和 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 在圆上得 <span class=\"gk-math\" data-tex=\"(h-3)^2+k^2=h^2+(k-1)^2\">(h-3)^2+k^2=h^2+(k-1)^2</span>，化简得 <span class=\"gk-math\" data-tex=\"3h-k=4\">3h-k=4</span>. 联立解得 <span class=\"gk-math\" data-tex=\"h=1\">h=1</span>，<span class=\"gk-math\" data-tex=\"k=-1\">k=-1</span>. 半径平方 <span class=\"gk-math\" data-tex=\"r^2=(1-3)^2+(-1)^2=5\">r^2=(1-3)^2+(-1)^2=5</span>，所以圆 <span class=\"gk-math\" data-tex=\"M\">M</span> 的方程为 <span class=\"gk-math\" data-tex=\"(x-1)^2+(y+1)^2=5\">(x-1)^2+(y+1)^2=5</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q15","paperId":"2022-national_paper_a_liberal","number":15,"type":"fill","score":5,"lessonIds":["e1-3.2"],"difficulty":"进阶","hint":"将 y=2x 代入双曲线方程，先找没有实数交点时 a、b 的关系。","legacy":false,"legacyReason":"","searchText":"记双曲线 C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1 （ a>0 ， b>0 ）的离心率为 e ，写出满足条件“直线 y=2x 与 C 无公共点”的 e 的一个值 ________ . ","questionHtml":"记双曲线 <span class=\"gk-math\" data-tex=\"C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1\">C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>）的离心率为 <span class=\"gk-math\" data-tex=\"e\">e</span>，写出满足条件“直线 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 与 <span class=\"gk-math\" data-tex=\"C\">C</span> 无公共点”的 <span class=\"gk-math\" data-tex=\"e\">e</span> 的一个值<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"2","answerKey":"","solutionHtml":"将 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 代入双曲线方程得 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac1{a^2}-\\dfrac4{b^2}\\right)x^2=1\">\\left(\\dfrac1{a^2}-\\dfrac4{b^2}\\right)x^2=1</span>，它与双曲线无公共点当且仅当 <span class=\"gk-math\" data-tex=\"\\dfrac1{a^2}-\\dfrac4{b^2}\\le0\">\\dfrac1{a^2}-\\dfrac4{b^2}\\le0</span>，即 <span class=\"gk-math\" data-tex=\"\\dfrac ba\\le2\">\\dfrac ba\\le2</span>. 于是 <span class=\"gk-math\" data-tex=\"e=\\dfrac ca=\\sqrt{1+\\left(\\dfrac ba\\right)^2}\\le\\sqrt5\">e=\\dfrac ca=\\sqrt{1+\\left(\\dfrac ba\\right)^2}\\le\\sqrt5</span>，又 <span class=\"gk-math\" data-tex=\"e&gt;1\">e&gt;1</span>，故 <span class=\"gk-math\" data-tex=\"e\">e</span> 可取 <span class=\"gk-math\" data-tex=\"(1,\\sqrt5]\">(1,\\sqrt5]</span> 内的任意值，例如 <span class=\"gk-math\" data-tex=\"2\">2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q16","paperId":"2022-national_paper_a_liberal","number":16,"type":"fill","score":5,"lessonIds":["6.4","2.3"],"difficulty":"挑战","hint":"设 BD=x、CD=2x，在两个小三角形中分别用余弦定理表示 AB² 和 AC²。","legacy":false,"legacyReason":"","searchText":"已知 \\triangle ABC 中，点 D 在边 BC 上， \\angle ADB=120^\\circ ， AD=2 ，且 CD=2BD . 当 \\dfrac{AC}{AB} 取得最小值时， BD= ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，点 <span class=\"gk-math\" data-tex=\"D\">D</span> 在边 <span class=\"gk-math\" data-tex=\"BC\">BC</span> 上，<span class=\"gk-math\" data-tex=\"\\angle ADB=120^\\circ\">\\angle ADB=120^\\circ</span>，<span class=\"gk-math\" data-tex=\"AD=2\">AD=2</span>，且 <span class=\"gk-math\" data-tex=\"CD=2BD\">CD=2BD</span>. 当 <span class=\"gk-math\" data-tex=\"\\dfrac{AC}{AB}\">\\dfrac{AC}{AB}</span> 取得最小值时，<span class=\"gk-math\" data-tex=\"BD=\">BD=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\sqrt{3}-1\">\\sqrt{3}-1</span>","answerKey":"","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"BD=x&gt;0\">BD=x&gt;0</span>，则 <span class=\"gk-math\" data-tex=\"CD=2x\">CD=2x</span>，且 <span class=\"gk-math\" data-tex=\"\\angle ADC=180^\\circ-\\angle ADB=60^\\circ\">\\angle ADC=180^\\circ-\\angle ADB=60^\\circ</span>. 在 <span class=\"gk-math\" data-tex=\"\\triangle ABD\">\\triangle ABD</span> 中，<span class=\"gk-math\" data-tex=\"AB^2=AD^2+BD^2-2\\cdot AD\\cdot BD\\cos120^\\circ=4+x^2+2x\">AB^2=AD^2+BD^2-2\\cdot AD\\cdot BD\\cos120^\\circ=4+x^2+2x</span>；在 <span class=\"gk-math\" data-tex=\"\\triangle ADC\">\\triangle ADC</span> 中，<span class=\"gk-math\" data-tex=\"AC^2=AD^2+CD^2-2\\cdot AD\\cdot CD\\cos60^\\circ=4+4x^2-4x\">AC^2=AD^2+CD^2-2\\cdot AD\\cdot CD\\cos60^\\circ=4+4x^2-4x</span>. 所以 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac{AC}{AB}\\right)^2=\\dfrac{4x^2-4x+4}{x^2+2x+4}\">\\left(\\dfrac{AC}{AB}\\right)^2=\\dfrac{4x^2-4x+4}{x^2+2x+4}</span>.<br><br>令 <span class=\"gk-math\" data-tex=\"g(x)=\\dfrac{4x^2-4x+4}{x^2+2x+4}\">g(x)=\\dfrac{4x^2-4x+4}{x^2+2x+4}</span>，由 <span class=\"gk-math\" data-tex=\"g&#x27;(x)=0\">g&#x27;(x)=0</span> 得 <span class=\"gk-math\" data-tex=\"(8x-4)(x^2+2x+4)-(4x^2-4x+4)(2x+2)=0\">(8x-4)(x^2+2x+4)-(4x^2-4x+4)(2x+2)=0</span>，化简得 <span class=\"gk-math\" data-tex=\"12x^2+24x-24=0\">12x^2+24x-24=0</span>，即 <span class=\"gk-math\" data-tex=\"x^2+2x-2=0\">x^2+2x-2=0</span>，解得 <span class=\"gk-math\" data-tex=\"x=\\sqrt3-1\">x=\\sqrt3-1</span>（舍去负值）. 此时取得最小值，所以 <span class=\"gk-math\" data-tex=\"BD=\\sqrt3-1\">BD=\\sqrt3-1</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q17","paperId":"2022-national_paper_a_liberal","number":17,"type":"written","score":12,"lessonIds":["10.3","e3-8.3"],"difficulty":"基础","hint":"A 公司共有 260 班、B 公司共有 240 班；先分别用准点班次除以各自总班次。","legacy":false,"legacyReason":"","searchText":"甲，乙两城之间的长途客车均由 A 和 B 两家公司运营，为了解这两家公司长途客车的运行情况，随机调查了甲，乙两城之间的 500 个班次，得到下面列联表： 准点班次数 未准点班次数 A 240 20 B 210 30 根据上表，分别估计这两家公司甲，乙两城之间的长途客车准点的概率； 能否有 90\\% 的把握认为甲，乙两城之间的长途客车是否准点与客车所属公司有关？ 附： K^2=\\dfrac{n\\left(ad-bc\\right)^2}{\\left(a+b\\right)\\left(c+d\\right)\\left(a+c\\right)\\left(b+d\\right)} P\\left(K^2\\ge k\\right) 0.100 0.050 0.010 k 2.706 3.841 6.635 ","questionHtml":"甲，乙两城之间的长途客车均由 <span class=\"gk-math\" data-tex=\"A\">A</span> 和 <span class=\"gk-math\" data-tex=\"B\">B</span> 两家公司运营，为了解这两家公司长途客车的运行情况，随机调查了甲，乙两城之间的 <span class=\"gk-math\" data-tex=\"500\">500</span> 个班次，得到下面列联表：<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td>准点班次数</td><td>未准点班次数</td></tr><tr><td><span class=\"gk-math\" data-tex=\"A\">A</span></td><td>240</td><td>20</td></tr><tr><td><span class=\"gk-math\" data-tex=\"B\">B</span></td><td>210</td><td>30</td></tr></table></div></div><br><br><ol class=\"gk-subparts\"><li>根据上表，分别估计这两家公司甲，乙两城之间的长途客车准点的概率；</li><li>能否有 <span class=\"gk-math\" data-tex=\"90\\%\">90\\%</span> 的把握认为甲，乙两城之间的长途客车是否准点与客车所属公司有关？</li></ol><br><br>附：<span class=\"gk-math\" data-tex=\"K^2=\\dfrac{n\\left(ad-bc\\right)^2}{\\left(a+b\\right)\\left(c+d\\right)\\left(a+c\\right)\\left(b+d\\right)}\">K^2=\\dfrac{n\\left(ad-bc\\right)^2}{\\left(a+b\\right)\\left(c+d\\right)\\left(a+c\\right)\\left(b+d\\right)}</span><br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><span class=\"gk-math\" data-tex=\"P\\left(K^2\\ge k\\right)\">P\\left(K^2\\ge k\\right)</span></td><td>0.100</td><td>0.050</td><td>0.010</td></tr><tr><td><span class=\"gk-math\" data-tex=\"k\">k</span></td><td>2.706</td><td>3.841</td><td>6.635</td></tr></table></div></div>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>公司 <span class=\"gk-math\" data-tex=\"A\">A</span> 共调查 <span class=\"gk-math\" data-tex=\"240+20=260\">240+20=260</span> 个班次，其中准点 <span class=\"gk-math\" data-tex=\"240\">240</span> 个，准点概率的估计值为 <span class=\"gk-math\" data-tex=\"\\dfrac{240}{260}=\\dfrac{12}{13}\">\\dfrac{240}{260}=\\dfrac{12}{13}</span>；公司 <span class=\"gk-math\" data-tex=\"B\">B</span> 共调查 <span class=\"gk-math\" data-tex=\"210+30=240\">210+30=240</span> 个班次，其中准点 <span class=\"gk-math\" data-tex=\"210\">210</span> 个，准点概率的估计值为 <span class=\"gk-math\" data-tex=\"\\dfrac{210}{240}=\\dfrac78\">\\dfrac{210}{240}=\\dfrac78</span>.</li><li>由列联表，<span class=\"gk-math\" data-tex=\"a=240\">a=240</span>，<span class=\"gk-math\" data-tex=\"b=20\">b=20</span>，<span class=\"gk-math\" data-tex=\"c=210\">c=210</span>，<span class=\"gk-math\" data-tex=\"d=30\">d=30</span>，<span class=\"gk-math\" data-tex=\"n=500\">n=500</span>，所以 <span class=\"gk-math\" data-tex=\"K^2=\\dfrac{500\\times(240\\times30-20\\times210)^2}{260\\times240\\times450\\times50}=\\dfrac{500\\times3000^2}{1404000000}\\approx3.205\">K^2=\\dfrac{500\\times(240\\times30-20\\times210)^2}{260\\times240\\times450\\times50}=\\dfrac{500\\times3000^2}{1404000000}\\approx3.205</span>. 因为 <span class=\"gk-math\" data-tex=\"3.205&gt;2.706\">3.205&gt;2.706</span>，所以有 <span class=\"gk-math\" data-tex=\"90\\%\">90\\%</span> 的把握认为长途客车是否准点与客车所属公司有关.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q18","paperId":"2022-national_paper_a_liberal","number":18,"type":"written","score":12,"lessonIds":["e2-4.1","e2-4.2","e2-4.3"],"difficulty":"进阶","hint":"先把已知式乘以 n，再写出 n−1 时的式子相减，利用 S_n−S_{n−1}=a_n。","legacy":false,"legacyReason":"","searchText":"记 S_n 为数列 \\{a_n\\} 的前 n 项和. 已知 \\dfrac{2S_n}{n}+n=2a_n+1 . 证明： \\{a_n\\} 是等差数列； 若 a_4 ， a_7 ， a_9 成等比数列，求 S_n 的最小值. ","questionHtml":"记 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 为数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和. 已知 <span class=\"gk-math\" data-tex=\"\\dfrac{2S_n}{n}+n=2a_n+1\">\\dfrac{2S_n}{n}+n=2a_n+1</span>.<br><br><ol class=\"gk-subparts\"><li>证明：<span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 是等差数列；</li><li>若 <span class=\"gk-math\" data-tex=\"a_4\">a_4</span>，<span class=\"gk-math\" data-tex=\"a_7\">a_7</span>，<span class=\"gk-math\" data-tex=\"a_9\">a_9</span> 成等比数列，求 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 的最小值.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"\\dfrac{2S_n}{n}+n=2a_n+1\">\\dfrac{2S_n}{n}+n=2a_n+1</span> 得 <span class=\"gk-math\" data-tex=\"2S_n=2na_n+n-n^2\">2S_n=2na_n+n-n^2</span>. 当 <span class=\"gk-math\" data-tex=\"n\\ge2\">n\\ge2</span> 时，写出 <span class=\"gk-math\" data-tex=\"n-1\">n-1</span> 的情形 <span class=\"gk-math\" data-tex=\"2S_{n-1}=2(n-1)a_{n-1}+(n-1)-(n-1)^2\">2S_{n-1}=2(n-1)a_{n-1}+(n-1)-(n-1)^2</span>，两式相减得 <span class=\"gk-math\" data-tex=\"2a_n=2na_n-2(n-1)a_{n-1}-2n+2\">2a_n=2na_n-2(n-1)a_{n-1}-2n+2</span>，即 <span class=\"gk-math\" data-tex=\"2(n-1)(a_n-a_{n-1})=2(n-1)\">2(n-1)(a_n-a_{n-1})=2(n-1)</span>. 因为 <span class=\"gk-math\" data-tex=\"n\\ge2\">n\\ge2</span>，所以 <span class=\"gk-math\" data-tex=\"a_n-a_{n-1}=1\">a_n-a_{n-1}=1</span>，故 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 是公差为 <span class=\"gk-math\" data-tex=\"1\">1</span> 的等差数列.</li><li>设 <span class=\"gk-math\" data-tex=\"a_1=t\">a_1=t</span>，则 <span class=\"gk-math\" data-tex=\"a_n=t+n-1\">a_n=t+n-1</span>. 由 <span class=\"gk-math\" data-tex=\"a_4\">a_4</span>，<span class=\"gk-math\" data-tex=\"a_7\">a_7</span>，<span class=\"gk-math\" data-tex=\"a_9\">a_9</span> 成等比数列得 <span class=\"gk-math\" data-tex=\"a_7^2=a_4a_9\">a_7^2=a_4a_9</span>，即 <span class=\"gk-math\" data-tex=\"(t+6)^2=(t+3)(t+8)\">(t+6)^2=(t+3)(t+8)</span>，化简得 <span class=\"gk-math\" data-tex=\"12t+36=11t+24\">12t+36=11t+24</span>，解得 <span class=\"gk-math\" data-tex=\"t=-12\">t=-12</span>. 所以 <span class=\"gk-math\" data-tex=\"a_n=n-13\">a_n=n-13</span>，从而 <span class=\"gk-math\" data-tex=\"S_n=\\dfrac{n(a_1+a_n)}2=\\dfrac{n(n-25)}2=\\dfrac12(n^2-25n)\">S_n=\\dfrac{n(a_1+a_n)}2=\\dfrac{n(n-25)}2=\\dfrac12(n^2-25n)</span>. 当 <span class=\"gk-math\" data-tex=\"n=12\">n=12</span> 或 <span class=\"gk-math\" data-tex=\"n=13\">n=13</span> 时 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 取最小值 <span class=\"gk-math\" data-tex=\"\\dfrac12\\times(144-300)=-78\">\\dfrac12\\times(144-300)=-78</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q19","paperId":"2022-national_paper_a_liberal","number":19,"type":"written","score":12,"lessonIds":["8.5","8.3","8.6"],"difficulty":"进阶","hint":"连接正三角形的顶点与底边中点，先利用等高关系证明 EF 平行底面。","legacy":false,"legacyReason":"","searchText":"小明同学参加综合实践活动，设计了一个封闭的包装盒，包装盒如图所示：底面 ABCD 是边长为 8\\mathrm{~cm} 的正方形， \\triangle EAB ， \\triangle FBC ， \\triangle GCD ， \\triangle HDA 均为正三角形，且它们所在的平面都与平面 ABCD 垂直. 证明： EF\\parallel 平面 ABCD ； 求该包装盒的容积（不计包装盒材料的厚度）. ","questionHtml":"小明同学参加综合实践活动，设计了一个封闭的包装盒，包装盒如图所示：底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 是边长为 <span class=\"gk-math\" data-tex=\"8\\mathrm{~cm}\">8\\mathrm{~cm}</span> 的正方形，<span class=\"gk-math\" data-tex=\"\\triangle EAB\">\\triangle EAB</span>，<span class=\"gk-math\" data-tex=\"\\triangle FBC\">\\triangle FBC</span>，<span class=\"gk-math\" data-tex=\"\\triangle GCD\">\\triangle GCD</span>，<span class=\"gk-math\" data-tex=\"\\triangle HDA\">\\triangle HDA</span> 均为正三角形，且它们所在的平面都与平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 垂直.<br><br><ol class=\"gk-subparts\"><li>证明：<span class=\"gk-math\" data-tex=\"EF\\parallel\">EF\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>；</li><li>求该包装盒的容积（不计包装盒材料的厚度）.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,438px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q19_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/national_paper_a_liberal/q19_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"422\" height=\"401\" style=\"aspect-ratio:422/401;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"\\triangle EAB\">\\triangle EAB</span> 为正三角形且所在平面垂直于平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，设 <span class=\"gk-math\" data-tex=\"M\">M</span> 为 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点，则 <span class=\"gk-math\" data-tex=\"EM\\perp AB\">EM\\perp AB</span>，从而 <span class=\"gk-math\" data-tex=\"EM\\perp\">EM\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，且 <span class=\"gk-math\" data-tex=\"EM=\\dfrac{\\sqrt3}2\\times8=4\\sqrt3\">EM=\\dfrac{\\sqrt3}2\\times8=4\\sqrt3</span>. 同理 <span class=\"gk-math\" data-tex=\"F\">F</span>，<span class=\"gk-math\" data-tex=\"G\">G</span>，<span class=\"gk-math\" data-tex=\"H\">H</span> 分别到对应边的中点 <span class=\"gk-math\" data-tex=\"N\">N</span>，<span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 的垂线段都垂直于平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，长度均为 <span class=\"gk-math\" data-tex=\"4\\sqrt3\">4\\sqrt3</span>. 于是 <span class=\"gk-math\" data-tex=\"E\">E</span>，<span class=\"gk-math\" data-tex=\"F\">F</span>，<span class=\"gk-math\" data-tex=\"G\">G</span>，<span class=\"gk-math\" data-tex=\"H\">H</span> 到平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 的距离相等，所以 <span class=\"gk-math\" data-tex=\"EF\">EF</span> 与平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 平行，即 <span class=\"gk-math\" data-tex=\"EF\\parallel\">EF\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>.</li><li>建立空间直角坐标系，取 <span class=\"gk-math\" data-tex=\"A(0,0,0)\">A(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"B(8,0,0)\">B(8,0,0)</span>，<span class=\"gk-math\" data-tex=\"C(8,8,0)\">C(8,8,0)</span>，<span class=\"gk-math\" data-tex=\"D(0,8,0)\">D(0,8,0)</span>. 由第（1）问，<span class=\"gk-math\" data-tex=\"E\">E</span>，<span class=\"gk-math\" data-tex=\"F\">F</span>，<span class=\"gk-math\" data-tex=\"G\">G</span>，<span class=\"gk-math\" data-tex=\"H\">H</span> 分别在各边中点正上方，高度为 <span class=\"gk-math\" data-tex=\"h=4\\sqrt3\">h=4\\sqrt3</span>，即 <span class=\"gk-math\" data-tex=\"E(4,0,h)\">E(4,0,h)</span>，<span class=\"gk-math\" data-tex=\"F(8,4,h)\">F(8,4,h)</span>，<span class=\"gk-math\" data-tex=\"G(4,8,h)\">G(4,8,h)</span>，<span class=\"gk-math\" data-tex=\"H(0,4,h)\">H(0,4,h)</span>. 该包装盒可看作以正方形 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 为底、高为 <span class=\"gk-math\" data-tex=\"h\">h</span> 的正四棱柱，在四个角上各去掉一个全等的三棱锥.<br><br>以角点 <span class=\"gk-math\" data-tex=\"A\">A</span> 处为例，去掉的三棱锥以 <span class=\"gk-math\" data-tex=\"A(0,0,0)\">A(0,0,0)</span> 为顶点，底面为等腰直角三角形，两条直角边长均为 <span class=\"gk-math\" data-tex=\"4\">4</span>，面积为 <span class=\"gk-math\" data-tex=\"\\dfrac12\\times4\\times4=8\">\\dfrac12\\times4\\times4=8</span>，该三棱锥的高为 <span class=\"gk-math\" data-tex=\"h\">h</span>. 所以每个三棱锥的体积为 <span class=\"gk-math\" data-tex=\"\\dfrac13\\times8\\times h=\\dfrac{8h}3\">\\dfrac13\\times8\\times h=\\dfrac{8h}3</span>，四个角共去掉 <span class=\"gk-math\" data-tex=\"\\dfrac{32h}3\">\\dfrac{32h}3</span>.<br><br>正四棱柱的体积为 <span class=\"gk-math\" data-tex=\"8^2h=64h\">8^2h=64h</span>，所以包装盒的容积为 <span class=\"gk-math\" data-tex=\"64h-\\dfrac{32h}3=\\dfrac{160h}3=\\dfrac{160}3\\times4\\sqrt3=\\dfrac{640\\sqrt3}3\\mathrm{~cm}^3\">64h-\\dfrac{32h}3=\\dfrac{160h}3=\\dfrac{160}3\\times4\\sqrt3=\\dfrac{640\\sqrt3}3\\mathrm{~cm}^3</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q20","paperId":"2022-national_paper_a_liberal","number":20,"type":"written","score":12,"lessonIds":["e2-5.1","e2-5.3"],"difficulty":"挑战","hint":"先求两条曲线的导数；公切线要求斜率相等，而且切线方程也相同。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=x^3-x ， g(x)=x^2+a ，曲线 y=f(x) 在点 \\left(x_1,f(x_1)\\right) 处的切线也是曲线 y=g(x) 的切线. 若 x_1=-1 ，求 a ； 求 a 的取值范围. ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=x^3-x\">f(x)=x^3-x</span>，<span class=\"gk-math\" data-tex=\"g(x)=x^2+a\">g(x)=x^2+a</span>，曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"\\left(x_1,f(x_1)\\right)\">\\left(x_1,f(x_1)\\right)</span> 处的切线也是曲线 <span class=\"gk-math\" data-tex=\"y=g(x)\">y=g(x)</span> 的切线.<br><br><ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"x_1=-1\">x_1=-1</span>，求 <span class=\"gk-math\" data-tex=\"a\">a</span>；</li><li>求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li><span class=\"gk-math\" data-tex=\"f&#x27;(x)=3x^2-1\">f&#x27;(x)=3x^2-1</span>，当 <span class=\"gk-math\" data-tex=\"x_1=-1\">x_1=-1</span> 时 <span class=\"gk-math\" data-tex=\"f(-1)=0\">f(-1)=0</span>，<span class=\"gk-math\" data-tex=\"f&#x27;(-1)=2\">f&#x27;(-1)=2</span>，切线方程为 <span class=\"gk-math\" data-tex=\"y=2(x+1)=2x+2\">y=2(x+1)=2x+2</span>. 该直线与 <span class=\"gk-math\" data-tex=\"y=g(x)\">y=g(x)</span> 相切，设切点横坐标为 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>，则 <span class=\"gk-math\" data-tex=\"g&#x27;(x_0)=2x_0=2\">g&#x27;(x_0)=2x_0=2</span>，所以 <span class=\"gk-math\" data-tex=\"x_0=1\">x_0=1</span>. 由切点在切线上得 <span class=\"gk-math\" data-tex=\"g(1)=1+a=2\\times1+2=4\">g(1)=1+a=2\\times1+2=4</span>，所以 <span class=\"gk-math\" data-tex=\"a=3\">a=3</span>.</li><li>曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x_1\">x_1</span> 处的切线为 <span class=\"gk-math\" data-tex=\"y-(x_1^3-x_1)=(3x_1^2-1)(x-x_1)\">y-(x_1^3-x_1)=(3x_1^2-1)(x-x_1)</span>，即 <span class=\"gk-math\" data-tex=\"y=(3x_1^2-1)x-2x_1^3\">y=(3x_1^2-1)x-2x_1^3</span>. 它与 <span class=\"gk-math\" data-tex=\"y=x^2+a\">y=x^2+a</span> 相切，则方程 <span class=\"gk-math\" data-tex=\"x^2+a=(3x_1^2-1)x-2x_1^3\">x^2+a=(3x_1^2-1)x-2x_1^3</span> 有唯一解，即 <span class=\"gk-math\" data-tex=\"x^2-(3x_1^2-1)x+(a+2x_1^3)=0\">x^2-(3x_1^2-1)x+(a+2x_1^3)=0</span> 的判别式为零：<span class=\"gk-math\" data-tex=\"(3x_1^2-1)^2-4(a+2x_1^3)=0\">(3x_1^2-1)^2-4(a+2x_1^3)=0</span>，解得 <span class=\"gk-math\" data-tex=\"a=\\dfrac{(3x_1^2-1)^2-8x_1^3}4=\\dfrac{9x_1^4-8x_1^3-6x_1^2+1}4\">a=\\dfrac{(3x_1^2-1)^2-8x_1^3}4=\\dfrac{9x_1^4-8x_1^3-6x_1^2+1}4</span>.<br><br>令 <span class=\"gk-math\" data-tex=\"\\varphi(t)=9t^4-8t^3-6t^2+1\">\\varphi(t)=9t^4-8t^3-6t^2+1</span>，则 <span class=\"gk-math\" data-tex=\"\\varphi&#x27;(t)=12t(3t+1)(t-1)\">\\varphi&#x27;(t)=12t(3t+1)(t-1)</span>. 由 <span class=\"gk-math\" data-tex=\"\\varphi&#x27;(t)\">\\varphi&#x27;(t)</span> 的符号可知 <span class=\"gk-math\" data-tex=\"\\varphi(t)\">\\varphi(t)</span> 在 <span class=\"gk-math\" data-tex=\"t=-1\">t=-1</span> 附近递减、在 <span class=\"gk-math\" data-tex=\"t=-\\dfrac13\">t=-\\dfrac13</span> 处取局部极小值 <span class=\"gk-math\" data-tex=\"\\dfrac{20}{27}\">\\dfrac{20}{27}</span>、在 <span class=\"gk-math\" data-tex=\"t=0\">t=0</span> 处取局部极大值 <span class=\"gk-math\" data-tex=\"1\">1</span>、在 <span class=\"gk-math\" data-tex=\"t=1\">t=1</span> 处取全局最小值 <span class=\"gk-math\" data-tex=\"-4\">-4</span>，且当 <span class=\"gk-math\" data-tex=\"t\\to\\pm\\infty\">t\\to\\pm\\infty</span> 时 <span class=\"gk-math\" data-tex=\"\\varphi(t)\\to+\\infty\">\\varphi(t)\\to+\\infty</span>. 所以 <span class=\"gk-math\" data-tex=\"\\varphi(t)\\ge-4\">\\varphi(t)\\ge-4</span>，从而 <span class=\"gk-math\" data-tex=\"a\\ge\\dfrac{-4}4=-1\">a\\ge\\dfrac{-4}4=-1</span>，即 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围为 <span class=\"gk-math\" data-tex=\"[-1,+\\infty)\">[-1,+\\infty)</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q21","paperId":"2022-national_paper_a_liberal","number":21,"type":"written","score":12,"lessonIds":["e1-3.3","e1-2.1"],"difficulty":"挑战","hint":"MD 垂直 x 轴时 M 的横坐标为 p，用抛物线焦半径公式先求 p。","legacy":false,"legacyReason":"","searchText":"设抛物线 C:y^2=2px （ p>0 ）的焦点为 F ，点 D\\left(p,0\\right) ，过 F 的直线交 C 于 M ， N 两点. 当直线 MD 垂直于 x 轴时， \\lvert MF\\rvert=3 . 求 C 的方程； 设直线 MD ， ND 与 C 的另一个交点分别为 A ， B ，记直线 MN ， AB 的倾斜角分别为 \\alpha ， \\beta . 当 \\alpha-\\beta 取得最大值时，求直线 AB 的方程. ","questionHtml":"设抛物线 <span class=\"gk-math\" data-tex=\"C:y^2=2px\">C:y^2=2px</span>（<span class=\"gk-math\" data-tex=\"p&gt;0\">p&gt;0</span>）的焦点为 <span class=\"gk-math\" data-tex=\"F\">F</span>，点 <span class=\"gk-math\" data-tex=\"D\\left(p,0\\right)\">D\\left(p,0\\right)</span>，过 <span class=\"gk-math\" data-tex=\"F\">F</span> 的直线交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于 <span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 两点. 当直线 <span class=\"gk-math\" data-tex=\"MD\">MD</span> 垂直于 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴时，<span class=\"gk-math\" data-tex=\"\\lvert MF\\rvert=3\">\\lvert MF\\rvert=3</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"C\">C</span> 的方程；</li><li>设直线 <span class=\"gk-math\" data-tex=\"MD\">MD</span>，<span class=\"gk-math\" data-tex=\"ND\">ND</span> 与 <span class=\"gk-math\" data-tex=\"C\">C</span> 的另一个交点分别为 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，记直线 <span class=\"gk-math\" data-tex=\"MN\">MN</span>，<span class=\"gk-math\" data-tex=\"AB\">AB</span> 的倾斜角分别为 <span class=\"gk-math\" data-tex=\"\\alpha\">\\alpha</span>，<span class=\"gk-math\" data-tex=\"\\beta\">\\beta</span>. 当 <span class=\"gk-math\" data-tex=\"\\alpha-\\beta\">\\alpha-\\beta</span> 取得最大值时，求直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的方程.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"\\lvert MF\\rvert=3\">\\lvert MF\\rvert=3</span>，当 <span class=\"gk-math\" data-tex=\"MD\\perp x\">MD\\perp x</span> 轴时 <span class=\"gk-math\" data-tex=\"M\">M</span> 的横坐标为 <span class=\"gk-math\" data-tex=\"p\">p</span>，代入 <span class=\"gk-math\" data-tex=\"y^2=2px\">y^2=2px</span> 得 <span class=\"gk-math\" data-tex=\"M(p,\\pm\\sqrt2p)\">M(p,\\pm\\sqrt2p)</span>. 焦点 <span class=\"gk-math\" data-tex=\"F\\left(\\dfrac p2,0\\right)\">F\\left(\\dfrac p2,0\\right)</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert MF\\rvert=\\sqrt{\\left(p-\\dfrac p2\\right)^2+2p^2}=\\dfrac32p=3\">\\lvert MF\\rvert=\\sqrt{\\left(p-\\dfrac p2\\right)^2+2p^2}=\\dfrac32p=3</span>，解得 <span class=\"gk-math\" data-tex=\"p=2\">p=2</span>. 故 <span class=\"gk-math\" data-tex=\"C\">C</span> 的方程为 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span>.</li><li>抛物线 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span> 上的点可记为 <span class=\"gk-math\" data-tex=\"(t^2,2t)\">(t^2,2t)</span>. 设 <span class=\"gk-math\" data-tex=\"M=(t_1^2,2t_1)\">M=(t_1^2,2t_1)</span>，<span class=\"gk-math\" data-tex=\"N=(t_2^2,2t_2)\">N=(t_2^2,2t_2)</span>. 因为弦 <span class=\"gk-math\" data-tex=\"MN\">MN</span> 过焦点 <span class=\"gk-math\" data-tex=\"F(1,0)\">F(1,0)</span>，所以 <span class=\"gk-math\" data-tex=\"t_1t_2=-1\">t_1t_2=-1</span>. 又点 <span class=\"gk-math\" data-tex=\"D(2,0)\">D(2,0)</span>，过 <span class=\"gk-math\" data-tex=\"D\">D</span> 的弦两端参数之积为 <span class=\"gk-math\" data-tex=\"-2\">-2</span>，故 <span class=\"gk-math\" data-tex=\"A\">A</span> 对应参数 <span class=\"gk-math\" data-tex=\"t_A=-\\dfrac2{t_1}\">t_A=-\\dfrac2{t_1}</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 对应参数 <span class=\"gk-math\" data-tex=\"t_B=-\\dfrac2{t_2}=2t_1\">t_B=-\\dfrac2{t_2}=2t_1</span>. 记 <span class=\"gk-math\" data-tex=\"u=t_1\">u=t_1</span>，则 <span class=\"gk-math\" data-tex=\"t_2=-\\dfrac1u\">t_2=-\\dfrac1u</span>.<br><br>直线 <span class=\"gk-math\" data-tex=\"MN\">MN</span> 的斜率 <span class=\"gk-math\" data-tex=\"\\tan\\alpha=\\dfrac{2t_1-2t_2}{t_1^2-t_2^2}=\\dfrac2{t_1+t_2}=\\dfrac{2u}{u^2-1}\">\\tan\\alpha=\\dfrac{2t_1-2t_2}{t_1^2-t_2^2}=\\dfrac2{t_1+t_2}=\\dfrac{2u}{u^2-1}</span>，直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的斜率 <span class=\"gk-math\" data-tex=\"\\tan\\beta=\\dfrac2{t_A+t_B}=\\dfrac2{2u-\\frac2u}=\\dfrac u{u^2-1}\">\\tan\\beta=\\dfrac2{t_A+t_B}=\\dfrac2{2u-\\frac2u}=\\dfrac u{u^2-1}</span>. 因而 <span class=\"gk-math\" data-tex=\"\\tan(\\alpha-\\beta)=\\dfrac{\\tan\\alpha-\\tan\\beta}{1+\\tan\\alpha\\tan\\beta}=\\dfrac{\\dfrac u{u^2-1}}{1+\\dfrac{2u^2}{(u^2-1)^2}}=\\dfrac{u(u^2-1)}{u^4+1}\">\\tan(\\alpha-\\beta)=\\dfrac{\\tan\\alpha-\\tan\\beta}{1+\\tan\\alpha\\tan\\beta}=\\dfrac{\\dfrac u{u^2-1}}{1+\\dfrac{2u^2}{(u^2-1)^2}}=\\dfrac{u(u^2-1)}{u^4+1}</span>.<br><br>令 <span class=\"gk-math\" data-tex=\"w=u-\\dfrac1u\">w=u-\\dfrac1u</span>，则 <span class=\"gk-math\" data-tex=\"w\\in\\R\">w\\in\\R</span>，且 <span class=\"gk-math\" data-tex=\"\\tan(\\alpha-\\beta)=\\dfrac{w}{w^2+2}\\le\\dfrac{\\sqrt2}4\">\\tan(\\alpha-\\beta)=\\dfrac{w}{w^2+2}\\le\\dfrac{\\sqrt2}4</span>，当且仅当 <span class=\"gk-math\" data-tex=\"w=\\sqrt2\">w=\\sqrt2</span> 时取等号，此时 <span class=\"gk-math\" data-tex=\"\\alpha-\\beta\">\\alpha-\\beta</span> 最大. 由 <span class=\"gk-math\" data-tex=\"u-\\dfrac1u=\\sqrt2\">u-\\dfrac1u=\\sqrt2</span> 得 <span class=\"gk-math\" data-tex=\"u^2-\\sqrt2u-1=0\">u^2-\\sqrt2u-1=0</span>. 直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的斜率 <span class=\"gk-math\" data-tex=\"=\\dfrac1w=\\dfrac1{\\sqrt2}\">=\\dfrac1w=\\dfrac1{\\sqrt2}</span>，且 <span class=\"gk-math\" data-tex=\"B=(4u^2,4u)\">B=(4u^2,4u)</span> 满足 <span class=\"gk-math\" data-tex=\"4u^2=\\sqrt2\\cdot4u+4\">4u^2=\\sqrt2\\cdot4u+4</span>，故 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的方程为 <span class=\"gk-math\" data-tex=\"x=\\sqrt2y+4\">x=\\sqrt2y+4</span>（即 <span class=\"gk-math\" data-tex=\"y=\\dfrac{\\sqrt2}2x-2\\sqrt2\">y=\\dfrac{\\sqrt2}2x-2\\sqrt2</span>）.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q22","paperId":"2022-national_paper_a_liberal","number":22,"type":"written","score":10,"lessonIds":["e1-3.3","e1-2.2"],"difficulty":"进阶","hint":"这是超出当前五册的参数方程与极坐标题；先用 t=y² 消去参数，并保留 y≥0。","legacy":true,"legacyReason":"","searchText":"在直角坐标系 xOy 中，曲线 C_1 的参数方程为 x=\\dfrac{2+t}{6} ， y=\\sqrt{t} （ t 为参数）；曲线 C_2 的参数方程为 x=-\\dfrac{2+s}{6} ， y=-\\sqrt{s} （ s 为参数）. 写出 C_1 的普通方程； 以坐标原点为极点， x 轴正半轴为极轴建立极坐标系，曲线 C_3 的极坐标方程为 2\\cos\\theta-\\sin\\theta=0 ，求 C_3 与 C_1 交点的直角坐标，及 C_3 与 C_2 交点的直角坐标. ","questionHtml":"在直角坐标系 <span class=\"gk-math\" data-tex=\"xOy\">xOy</span> 中，曲线 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 的参数方程为 <span class=\"gk-math\" data-tex=\"x=\\dfrac{2+t}{6}\">x=\\dfrac{2+t}{6}</span>，<span class=\"gk-math\" data-tex=\"y=\\sqrt{t}\">y=\\sqrt{t}</span>（<span class=\"gk-math\" data-tex=\"t\">t</span> 为参数）；曲线 <span class=\"gk-math\" data-tex=\"C_2\">C_2</span> 的参数方程为 <span class=\"gk-math\" data-tex=\"x=-\\dfrac{2+s}{6}\">x=-\\dfrac{2+s}{6}</span>，<span class=\"gk-math\" data-tex=\"y=-\\sqrt{s}\">y=-\\sqrt{s}</span>（<span class=\"gk-math\" data-tex=\"s\">s</span> 为参数）.<br><br><ol class=\"gk-subparts\"><li>写出 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 的普通方程；</li><li>以坐标原点为极点，<span class=\"gk-math\" data-tex=\"x\">x</span> 轴正半轴为极轴建立极坐标系，曲线 <span class=\"gk-math\" data-tex=\"C_3\">C_3</span> 的极坐标方程为 <span class=\"gk-math\" data-tex=\"2\\cos\\theta-\\sin\\theta=0\">2\\cos\\theta-\\sin\\theta=0</span>，求 <span class=\"gk-math\" data-tex=\"C_3\">C_3</span> 与 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 交点的直角坐标，及 <span class=\"gk-math\" data-tex=\"C_3\">C_3</span> 与 <span class=\"gk-math\" data-tex=\"C_2\">C_2</span> 交点的直角坐标.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"y=\\sqrt t\">y=\\sqrt t</span> 得 <span class=\"gk-math\" data-tex=\"t=y^2\">t=y^2</span>（<span class=\"gk-math\" data-tex=\"y\\ge0\">y\\ge0</span>），代入 <span class=\"gk-math\" data-tex=\"x=\\dfrac{2+t}6\">x=\\dfrac{2+t}6</span> 得 <span class=\"gk-math\" data-tex=\"x=\\dfrac{2+y^2}6\">x=\\dfrac{2+y^2}6</span>，所以 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 的普通方程为 <span class=\"gk-math\" data-tex=\"y^2=6x-2\">y^2=6x-2</span>（<span class=\"gk-math\" data-tex=\"y\\ge0\">y\\ge0</span>）.</li><li>曲线 <span class=\"gk-math\" data-tex=\"C_2\">C_2</span> 中 <span class=\"gk-math\" data-tex=\"y=-\\sqrt s\\le0\">y=-\\sqrt s\\le0</span>，由 <span class=\"gk-math\" data-tex=\"s=y^2\">s=y^2</span> 得 <span class=\"gk-math\" data-tex=\"x=-\\dfrac{2+y^2}6\">x=-\\dfrac{2+y^2}6</span>，即 <span class=\"gk-math\" data-tex=\"y^2=-6x-2\">y^2=-6x-2</span>（<span class=\"gk-math\" data-tex=\"y\\le0\">y\\le0</span>）. 极坐标方程 <span class=\"gk-math\" data-tex=\"2\\cos\\theta-\\sin\\theta=0\">2\\cos\\theta-\\sin\\theta=0</span> 化为直角坐标方程 <span class=\"gk-math\" data-tex=\"2x-y=0\">2x-y=0</span>，即 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span>.<br><br>将 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 代入 <span class=\"gk-math\" data-tex=\"y^2=6x-2\">y^2=6x-2</span> 得 <span class=\"gk-math\" data-tex=\"4x^2-6x+2=0\">4x^2-6x+2=0</span>，即 <span class=\"gk-math\" data-tex=\"2x^2-3x+1=0\">2x^2-3x+1=0</span>，解得 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 或 <span class=\"gk-math\" data-tex=\"x=\\dfrac12\">x=\\dfrac12</span>，对应交点 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac12,1\\right)\">\\left(\\dfrac12,1\\right)</span>，<span class=\"gk-math\" data-tex=\"(1,2)\">(1,2)</span>，均满足 <span class=\"gk-math\" data-tex=\"y\\ge0\">y\\ge0</span>，故 <span class=\"gk-math\" data-tex=\"C_3\">C_3</span> 与 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 的交点为 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac12,1\\right)\">\\left(\\dfrac12,1\\right)</span>，<span class=\"gk-math\" data-tex=\"(1,2)\">(1,2)</span>. 将 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 代入 <span class=\"gk-math\" data-tex=\"y^2=-6x-2\">y^2=-6x-2</span> 得 <span class=\"gk-math\" data-tex=\"4x^2+6x+2=0\">4x^2+6x+2=0</span>，即 <span class=\"gk-math\" data-tex=\"2x^2+3x+1=0\">2x^2+3x+1=0</span>，解得 <span class=\"gk-math\" data-tex=\"x=-\\dfrac12\">x=-\\dfrac12</span> 或 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>，对应交点 <span class=\"gk-math\" data-tex=\"\\left(-\\dfrac12,-1\\right)\">\\left(-\\dfrac12,-1\\right)</span>，<span class=\"gk-math\" data-tex=\"(-1,-2)\">(-1,-2)</span>，均满足 <span class=\"gk-math\" data-tex=\"y\\le0\">y\\le0</span>，故 <span class=\"gk-math\" data-tex=\"C_3\">C_3</span> 与 <span class=\"gk-math\" data-tex=\"C_2\">C_2</span> 的交点为 <span class=\"gk-math\" data-tex=\"\\left(-\\dfrac12,-1\\right)\">\\left(-\\dfrac12,-1\\right)</span>，<span class=\"gk-math\" data-tex=\"(-1,-2)\">(-1,-2)</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-national_paper_a_liberal-q23","paperId":"2022-national_paper_a_liberal","number":23,"type":"written","score":10,"lessonIds":["2.2","2.1"],"difficulty":"挑战","hint":"这是旧课标不等式选讲，超出当前五册；先将 a、b、2c 看作三个正数，比较平方和与和的平方。","legacy":true,"legacyReason":"","searchText":"已知 a ， b ， c 均为正数，且 a^2+b^2+4c^2=3 ，证明： a+b+2c\\le3 ； 若 b=2c ，则 \\dfrac{1}{a}+\\dfrac{1}{c}\\ge3 . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span> 均为正数，且 <span class=\"gk-math\" data-tex=\"a^2+b^2+4c^2=3\">a^2+b^2+4c^2=3</span>，证明：<br><br><ol class=\"gk-subparts\"><li><span class=\"gk-math\" data-tex=\"a+b+2c\\le3\">a+b+2c\\le3</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"b=2c\">b=2c</span>，则 <span class=\"gk-math\" data-tex=\"\\dfrac{1}{a}+\\dfrac{1}{c}\\ge3\">\\dfrac{1}{a}+\\dfrac{1}{c}\\ge3</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由柯西不等式，<span class=\"gk-math\" data-tex=\"(a+b+2c)^2\\le(1+1+1)(a^2+b^2+4c^2)=3\\times3=9\">(a+b+2c)^2\\le(1+1+1)(a^2+b^2+4c^2)=3\\times3=9</span>，所以 <span class=\"gk-math\" data-tex=\"a+b+2c\\le3\">a+b+2c\\le3</span>.</li><li>因为 <span class=\"gk-math\" data-tex=\"b=2c\">b=2c</span>，所以 <span class=\"gk-math\" data-tex=\"a^2+b^2+4c^2=a^2+8c^2=3\">a^2+b^2+4c^2=a^2+8c^2=3</span>. 由基本不等式， <span class=\"gk-math\" data-tex=\"\\dfrac1a+\\dfrac1c=\\dfrac1a+\\dfrac1{2c}+\\dfrac1{2c}\\ge3\\sqrt[3]{\\dfrac1{a\\cdot2c\\cdot2c}}=3\\sqrt[3]{\\dfrac1{4ac^2}}\">\\dfrac1a+\\dfrac1c=\\dfrac1a+\\dfrac1{2c}+\\dfrac1{2c}\\ge3\\sqrt[3]{\\dfrac1{a\\cdot2c\\cdot2c}}=3\\sqrt[3]{\\dfrac1{4ac^2}}</span>. 又 <span class=\"gk-math\" data-tex=\"3=a^2+8c^2=a^2+4c^2+4c^2\\ge3\\sqrt[3]{a^2\\cdot4c^2\\cdot4c^2}=3\\sqrt[3]{16a^2c^4}\">3=a^2+8c^2=a^2+4c^2+4c^2\\ge3\\sqrt[3]{a^2\\cdot4c^2\\cdot4c^2}=3\\sqrt[3]{16a^2c^4}</span>，所以 <span class=\"gk-math\" data-tex=\"16a^2c^4\\le1\">16a^2c^4\\le1</span>，即 <span class=\"gk-math\" data-tex=\"ac^2\\le\\dfrac14\">ac^2\\le\\dfrac14</span>. 于是 <span class=\"gk-math\" data-tex=\"\\dfrac1a+\\dfrac1c\\ge3\\sqrt[3]{\\dfrac1{4ac^2}}\\ge3\\sqrt[3]{\\dfrac1{4\\times\\frac14}}=3\">\\dfrac1a+\\dfrac1c\\ge3\\sqrt[3]{\\dfrac1{4ac^2}}\\ge3\\sqrt[3]{\\dfrac1{4\\times\\frac14}}=3</span>，命题得证.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
